typedef unsigned int nlUint32;
typedef int nlInt32;
typedef nlUint32 nslSourceId;
typedef nlUint32 nslSoundId;
typedef nlUint32 nslEmitterId;

template<class T>
class fifo_queue
{
  T *queue;
  short queue_max;
  short start;
  short end;
  short count;
public:
  short find(const T& index_to_find, short remove_flag);
};

struct nslSource
{
  bool used;
  bool looping;
  char fileName[48];
  int bank;
  nslSourceId myId;
  float length;
  float paddedLength;
  int type;
  nlUint32 gasSourceId;
  float rawVolume;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSound
{
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  nlUint32 gasInstanceId;
  nlInt32 pauseCount;
  nlInt32 dampenCount;
  nslSourceId myId;
  nslSourceId mySource;
  nslEmitterId myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslEmitter
{
  bool used;
  bool autoRelease;
  bool isALineEmitter;
  nslEmitterId myId;
  float startPosition[3];
  float endPosition[3];
  float position[3];
  fifo_queue<nslSoundId> emittedSounds;
};

struct nslSystem
{
  float listenerPo[16];
  nslSource sourceSlots[512];
  nslSound soundSlots[256];
  nslEmitter emitterSlots[256];
  nlUint32 sourceSlotsUsedCount;
  nlUint32 soundSlotsUsedCount;
  nlUint32 emitterSlotsUsedCount;
  nlInt32 firstInit;
  nlInt32 initialized;
  nlUint32 numBanks;
  fifo_queue<nslSoundId> queuedSounds;
};

extern nslSystem nsl;
extern bool _set3dVolume(nslSoundId whichSound);
extern int nslPs2GasRpc(int command, const char *strarg, int intarg0,
                       int intarg1, int intarg2, int intarg3);
extern void nslPlaySound(nslSoundId soundToPlay);
extern void nslStopSound(nslSoundId soundToStop);

#define GAS_INSTANCE_STEREO_FLAG_BIT 0x0080
#define GAS_INVALID_ID -1
#define GAS_RPC_ADD_INSTANCE 0x0008
#define GAS_RPC_STOP_INSTANCE 0x10b0
#define NSL_GET_SLOT_FROM_ID(x) (x&0x000003FF)
#define NSL_SMALL3D_SOUND_SIZE .5f

void _nslCheckAndMaybePlay3dSound(nslSound *theSound)
{
  int start = 0;
  if (theSound->pauseCount > 0)
	{
		_set3dVolume(theSound->myId);
    return;
	}
  if (theSound->looping) 
  {
    if (theSound->inRange)
    {
      theSound->inRange = _set3dVolume(theSound->myId);
      if (!theSound->inRange) 
      {
        nlUint32 gasInst2Stop = theSound->gasInstanceId;
        theSound->gasInstanceId = (nlUint32)GAS_INVALID_ID; 
        if (gasInst2Stop != (nlUint32)GAS_INVALID_ID)
          nslPs2GasRpc(GAS_RPC_STOP_INSTANCE, "", gasInst2Stop, 0, 0, 0);
        nsl.queuedSounds.find(theSound->myId, true);
        theSound->isReallyReady = false;
      }
    }
    else
    {
      theSound->inRange = _set3dVolume(theSound->myId);
      if (theSound->inRange) 
      {
        if (theSound->gasInstanceId == (nlUint32)GAS_INVALID_ID)
        {
          start++;
          theSound->gasInstanceId =  ~GAS_INSTANCE_STEREO_FLAG_BIT & nslPs2GasRpc(GAS_RPC_ADD_INSTANCE, "", nsl.sourceSlots[NSL_GET_SLOT_FROM_ID(theSound->mySource)].gasSourceId, 0, 0, 0);
          theSound->isReallyReady = false;
          if (theSound->gasInstanceId != (nlUint32)GAS_INVALID_ID)
          {
            nsl.queuedSounds.find(theSound->myId, true);
            nslPlaySound(theSound->myId);
          }
        }
        else
        {
          if (nsl.sourceSlots[NSL_GET_SLOT_FROM_ID(theSound->mySource)].length >= NSL_SMALL3D_SOUND_SIZE)
          {
            nsl.queuedSounds.find(theSound->myId, true);
            nslPlaySound(theSound->myId);
          }
          else
          {
          }
        }
      }
    } 

  }
  else
  {
    theSound->inRange = _set3dVolume(theSound->myId);
    if ((!theSound->inRange) &&
        (nsl.sourceSlots[NSL_GET_SLOT_FROM_ID(theSound->mySource)].length <= NSL_SMALL3D_SOUND_SIZE))
    {
      nslStopSound(theSound->myId);
    }
  }

}
